### Define and Check Chat Member Statuses (Python)

Source: https://docs.aiogram.dev/en/dev-3.x/_modules/aiogram/filters/chat_member_updated

This snippet defines classes and constants for representing and checking chat member statuses in aiogram. It includes markers for individual statuses (CREATOR, ADMINISTRATOR, MEMBER, etc.) and group markers that allow combining statuses using logical operators like OR (|), NOT (-), and transitions (>>). The `check` method within these classes determines if a given `ChatMember` object matches the defined status criteria.

```python
class _MemberStatusMarker:
    def __init__(self, name: str) -> None:
        self.name = name

    def __str__(self) -> str:
        return self.name

    def __repr__(self) -> str:
        return f"<{self._class_name__()}('{self.name}')>"

    def __or__(self, other: "_MemberStatusMarker") -> _MemberStatusGroupMarker:
        return _MemberStatusGroupMarker(self, other)

    def __invert__(self) -> _MemberStatusGroupMarker:
        return _MemberStatusGroupMarker(self, ~self)

    def __rshift__(self, other: "_MemberStatusMarker") -> _MemberStatusTransition:
        return _MemberStatusTransition(old=self, new=other)

    def check(self, *, member: ChatMember) -> bool:
        raise NotImplemented


class _MemberStatusGroupMarker(_MemberStatusMarker):
    def __init__(self, *statuses: _MemberStatusMarker | _MemberStatusGroupMarker) -> None:
        self.statuses = statuses

    def __str__(self) -> str:
        result = " | ".join(map(str, sorted(self.statuses, key=str)))
        if len(self.statuses) != 1:
            return f"({result})"
        return result

    def __or__(self, other: _MemberStatusMarker | _MemberStatusGroupMarker) -> "_MemberStatusGroupMarker":
        if isinstance(other, _MemberStatusGroupMarker):
            return _MemberStatusGroupMarker(*self.statuses, *other.statuses)
        return _MemberStatusGroupMarker(*self.statuses, other)

    def __invert__(self) -> "_MemberStatusGroupMarker":
        return _MemberStatusGroupMarker(self, ~self)

    def __rshift__(self, other: _MemberStatusMarker | _MemberStatusGroupMarker) -> _MemberStatusTransition:
        return _MemberStatusTransition(old=self, new=other)

    def check(self, *, member: ChatMember) -> bool:
        return any(status.check(member=member) for status in self.statuses)


class _MemberStatusTransition:
    __slots__ = (
        "new",
        "old",
    )

    def __init__(self, *, old: _MemberStatusGroupMarker, new: _MemberStatusGroupMarker) -> None:
        self.old = old
        self.new = new

    def __str__(self) -> str:
        return f"{self.old} >> {self.new}"

    def __invert__(self) -> Self:
        return type(self)(old=self.new, new=self.old)

    def check(self, *, old: ChatMember, new: ChatMember) -> bool:
        return self.old.check(member=old) and self.new.check(member=new)


CREATOR = _MemberStatusMarker("creator")
ADMINISTRATOR = _MemberStatusMarker("administrator")
MEMBER = _MemberStatusMarker("member")
RESTRICTED = _MemberStatusMarker("restricted")
LEFT = _MemberStatusMarker("left")
KICKED = _MemberStatusMarker("kicked")

IS_MEMBER = CREATOR | ADMINISTRATOR | MEMBER | +RESTRICTED
IS_ADMIN = CREATOR | ADMINISTRATOR
IS_NOT_MEMBER = LEFT | KICKED | -RESTRICTED

JOIN_TRANSITION = IS_NOT_MEMBER >> IS_MEMBER
LEAVE_TRANSITION = ~JOIN_TRANSITION
PROMOTED_TRANSITION = (MEMBER | RESTRICTED | LEFT | KICKED) >> ADMINISTRATOR

```

